document.addEventListener("DOMContentLoaded",()=>{document.querySelectorAll(".splash__sheet").forEach(e=>{const t=document.createDocumentFragment(),a=document.createElement("div");a.className="splash__spine",t.appendChild(a);for(let e=0;e<23;e++){const a=document.createElement("div");a.className="splash__line",a.style.top=8+4*e+"%",a.style.opacity=Math.max(.22,.22-.01*e).toFixed(2),t.appendChild(a)}e.appendChild(t)})});